// game.js – simple Asteroid Run implementation
// Targets <canvas id="game"></canvas> present in the HTML page.
// Controls: Arrow keys / WASD – left/right rotate, up thrust.

(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return console.error('Canvas with id "game" not found');
  const ctx = canvas.getContext('2d');
  const width = canvas.width = canvas.clientWidth || 800;
  const height = canvas.height = canvas.clientHeight || 600;

  // ----- Ship -----
  const ship = {
    x: width / 2,
    y: height * 0.8,
    angle: -Math.PI / 2, // pointing up
    radius: 10,
    vx: 0,
    vy: 0,
    shield: 100,
  };

  // ----- Input -----
  const keys = {};
  window.addEventListener('keydown', e => { keys[e.key.toLowerCase()] = true; });
  window.addEventListener('keyup', e => { keys[e.key.toLowerCase()] = false; });

  // ----- Asteroids -----
  const asteroids = [];
  const asteroidSpawnInterval = 1000; // ms
  let lastSpawn = 0;

  function spawnAsteroid() {
    const radius = 15 + Math.random() * 20;
    asteroids.push({
      x: Math.random() * width,
      y: -radius,
      vx: (Math.random() - 0.5) * 0.5,
      vy: 1 + Math.random() * 1.5,
      radius,
    });
  }

  // ----- Game Loop -----
  function update(dt) {
    // Ship controls
    if (keys['arrowleft'] || keys['a']) ship.angle -= 0.04;
    if (keys['arrowright'] || keys['d']) ship.angle += 0.04;
    if (keys['arrowup'] || keys['w']) {
      const thrust = 0.1;
      ship.vx += Math.cos(ship.angle) * thrust;
      ship.vy += Math.sin(ship.angle) * thrust;
    }
    // Apply velocity & simple damping
    ship.x += ship.vx;
    ship.y += ship.vy;
    ship.vx *= 0.99;
    ship.vy *= 0.99;
    // Keep ship inside bounds (wrap horizontally)
    if (ship.x < 0) ship.x += width;
    if (ship.x > width) ship.x -= width;
    if (ship.y < 0) ship.y = 0;
    if (ship.y > height) ship.y = height;

    // Asteroids movement
    for (let i = asteroids.length - 1; i >= 0; i--) {
      const a = asteroids[i];
      a.x += a.vx;
      a.y += a.vy;
      // Remove off‑screen
      if (a.y - a.radius > height) asteroids.splice(i, 1);
    }

    // Collision detection (circle vs circle)
    for (let i = asteroids.length - 1; i >= 0; i--) {
      const a = asteroids[i];
      const dx = a.x - ship.x;
      const dy = a.y - ship.y;
      const dist = Math.hypot(dx, dy);
      if (dist < a.radius + ship.radius) {
        ship.shield -= 20; // damage
        asteroids.splice(i, 1);
        if (ship.shield <= 0) {
          // Game over – stop animation loop
          cancelAnimationFrame(animId);
          alert('Game Over');
          return;
        }
      }
    }

    // Spawn new asteroids
    if (performance.now() - lastSpawn > asteroidSpawnInterval) {
      spawnAsteroid();
      lastSpawn = performance.now();
    }
  }

  function draw() {
    ctx.clearRect(0, 0, width, height);
    // Draw ship
    ctx.save();
    ctx.translate(ship.x, ship.y);
    ctx.rotate(ship.angle);
    ctx.beginPath();
    ctx.moveTo(15, 0);
    ctx.lineTo(-10, -8);
    ctx.lineTo(-10, 8);
    ctx.closePath();
    ctx.fillStyle = '#0f0';
    ctx.fill();
    ctx.restore();
    // Draw asteroids
    ctx.fillStyle = '#888';
    for (const a of asteroids) {
      ctx.beginPath();
      ctx.arc(a.x, a.y, a.radius, 0, Math.PI * 2);
      ctx.fill();
    }
    // Draw shield bar
    ctx.fillStyle = '#f00';
    ctx.fillRect(10, 10, 100, 10);
    ctx.fillStyle = '#0f0';
    ctx.fillRect(10, 10, ship.shield, 10);
    ctx.strokeStyle = '#000';
    ctx.strokeRect(10, 10, 100, 10);
  }

  let lastTime = 0;
  let animId;
  function loop(timestamp) {
    const dt = timestamp - lastTime;
    lastTime = timestamp;
    update(dt);
    draw();
    animId = requestAnimationFrame(loop);
  }
  animId = requestAnimationFrame(loop);
})();
